function ModalShell({title,onClose,busy,children}:{title:string;onClose:()=>void;busy:boolean;children:React.ReactNode}) {const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const before=document.activeElement as HTMLElement;const el=ref.current;const old=document.body.style.overflow;document.body.style.overflow='hidden';el?.querySelector<HTMLElement>('input,select,button')?.focus();const listener=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)onClose();if(e.key==='Tab'){const nodes=Array.from(el?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[]);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',listener);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',listener);before?.focus()}},[busy]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-header"><div><span className="eyebrow">KEEP IT SIMPLE</span><h2 id="modal-title">{title}</h2></div><button className="icon-button" onClick={onClose} disabled={busy} aria-label="Close dialog"><Icon name="close"/></button></div>{children}</div></div>}
