function TransactionDetail({entry:e,people,currentPersonId,canRemove,busy,onConfirm,onVoid}:{entry:Entry;people:Person[];currentPersonId:string;canRemove:boolean;busy:boolean;onConfirm:()=>Promise<any>;onVoid:()=>Promise<any>}){const name=(id:string)=>people.find(p=>p.id===id)?.name||'Former member';const [error,setError]=useState('');return <div className="transaction-detail"><div className={`detail-kind ${e.status==='pending'?'pending':''}`}><Icon name={e.kind==='payment'?'wallet':'bill'} size={19}/>{e.status==='void'?'Removed record':e.kind==='payment'?e.status==='pending'?'Awaiting recipient confirmation':'Confirmed payment':'Shared expense'}</div><h3>{e.title}</h3><div className="detail-amount">{money(e.amount)}</div><dl><div><dt>Date</dt><dd>{dateLabel(e.date,true)}</dd></div><div><dt>{e.kind==='payment'?'Sent by':'Paid by'}</dt><dd>{name(e.payerId)}</dd></div>{e.recipientId&&<div><dt>Received by</dt><dd>{name(e.recipientId)}</dd></div>}{e.vendor&&<div><dt>Store or vendor</dt><dd>{e.vendor}</dd></div>}{e.category&&<div><dt>Category</dt><dd>{e.category}</dd></div>}</dl>{e.kind==='expense'&&<div className="detail-splits"><h4>Everyone’s share</h4>{e.shares.map(sh=><div key={sh.personId}><span>{name(sh.personId)}</span><strong>{money(sh.amount)}</strong></div>)}</div>}{e.note&&<div className="detail-note"><span>A little note</span><p>{e.note}</p></div>}{e.status==='pending'&&<p className="detail-pending-note">{e.recipientId===currentPersonId?'Only confirm when you’ve received this payment.':'This payment won’t change balances until the recipient confirms it arrived.'}</p>}{e.status==='pending'&&e.recipientId===currentPersonId&&<button className="primary-button wide" disabled={busy} onClick={()=>onConfirm().catch(e=>setError(e.message))}><Icon name="check" size={18}/>{busy?'Confirming…':'I received this payment'}</button>}{e.status!=='void'&&canRemove&&<button className="remove-record" disabled={busy} onClick={()=>{if(window.confirm('Remove this record from balances? Its details will stay in the history.'))onVoid().catch(e=>setError(e.message))}}>Remove record from balances</button>}{error&&<p className="form-error" role="alert">{error}</p>}</div>}
function AuthScreen({s,onDemo,onComplete}:{s:TabbyStore;onDemo:()=>void;onComplete:()=>void}){const [tab,setTab]=useState<'signin'|'signup'|'reset'|'update'>(s.recovery?'update':'signin'),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');useEffect(()=>{if(s.mode==='cloud'&&!s.recovery)onComplete()},[s.mode,s.recovery]);const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{if(tab==='update'){if(!s.updatePassword)throw Error('Please return through the password reset link.');await s.updatePassword(password);onComplete();return}if(tab==='reset'){await s.resetPassword(email);setMessage('Check your email for a password reset link.');return}if(tab==='signup'){await s.signUp(name.trim(),email,password);setMessage('Check your email to confirm your account, then come back to sign in.')}else {await s.signIn(email,password);onComplete()}}catch(e){setError(e instanceof Error?e.message:'Please try again.')}finally{setBusy(false)}};return <div className="auth-shell"><section className="auth-story"><a className="brand" href="#" onClick={e=>{e.preventDefault();onDemo()}}><Cat/><span>tabby.</span></a><div className="auth-story-copy"><span className="auth-eyebrow">FOR THE THINGS YOU SHARE</span><h1>Little tabs.<br/>Close people.</h1><p>You bring the people.<br/>We’ll keep the tabs.</p><div className="auth-mini-card"><div className="avatar mint">A</div><div><strong>Sunday groceries</strong><span>A little tab, shared together.</span></div><span className="auth-card-check"><Icon name="check"/></span></div><div className="auth-mini-card second"><span className="avatar lilac"><Icon name="heart"/></span><div><strong>All even. All good.</strong><span>One less thing to keep in your head.</span></div></div></div><p className="auth-footer">Less keeping score. More keeping in touch.</p></section><main className="auth-form-side"><button className="auth-demo-link" onClick={onDemo}>Have a look around the demo</button><div className="auth-form-container">{s.invitePending&&<div className="success-message"><Icon name="link" size={18}/><span>Your circle is waiting. Sign in or create an account to accept your invitation.</span></div>}<span className="auth-small-cat"><Cat/></span><p className="eyebrow">YOUR PEOPLE. YOUR LITTLE SPACE.</p><h2>{tab==='signup'?'Make yourself at home.':tab==='update'?'A fresh password, a fresh start.':tab==='reset'?'Let’s get you back in.':'Welcome to the circle.'}</h2><p className="auth-subtitle">{tab==='signup'?'A clearer picture. A little less mental math.':tab==='update'?'Choose a strong new password to get back to your circle.':tab==='reset'?'We’ll send you a secure link to reset your password.':'Sign in to pick up right where you left off.'}</p>{tab!=='reset'&&tab!=='update'&&<div className="auth-tabs"><button className={tab==='signin'?'active':''} onClick={()=>{setTab('signin');setError('');setMessage('')}}>Sign in</button><button className={tab==='signup'?'active':''} onClick={()=>{setTab('signup');setError('');setMessage('')}}>Create account</button></div>}<form onSubmit={submit}>{tab==='signup'&&<div className="form-field"><label htmlFor="auth-name">Your name</label><input id="auth-name" value={name} onChange={e=>setName(e.target.value)} required maxLength={60} autoComplete="name" placeholder="What should we call you?"/></div>}{tab!=='update'&&<div className="form-field"><label htmlFor="auth-email">Email address</label><input id="auth-email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email" placeholder="you@example.com"/></div>}{tab!=='reset'&&<div className="form-field"><label htmlFor="auth-password">Password</label><input id="auth-password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={tab==='signup'||tab==='update'?10:1} autoComplete={tab==='signup'||tab==='update'?'new-password':'current-password'} placeholder={tab==='signup'||tab==='update'?'At least 10 characters':'Your password'}/></div>}{error&&<div className="form-error" role="alert">{error}</div>}{s.error&&s.error!==error&&<div className="form-error" role="alert">{s.error}</div>}{message&&<div className="success-message" role="status"><Icon name="check" size={18}/>{message}</div>}<button className="primary-button wide auth-submit" disabled={busy}>{busy?'Just a moment…':tab==='signup'?'Create your account':tab==='reset'?'Send reset link':tab==='update'?'Save new password':'Sign in'}</button></form>{tab!=='update'&&<button className="forgot-password" onClick={()=>{setTab(tab==='reset'?'signin':'reset');setError('');setMessage('')}}>{tab==='reset'?'Back to sign in':'Forgot your password?'}</button>}<p className="auth-privacy"><Icon name="shield" size={16}/> Private circles. Shared only with your people.</p></div></main></div>}
